// ============================================================
// NAVIGATION ENTRE LES SLIDES
// Chaque slide est une <section class="slide">. On affiche une
// seule slide à la fois en lui ajoutant la classe "active".
// ============================================================
const slides = Array.from(document.querySelectorAll('.slide'));
const totalSlides = slides.length;
let currentSlide = 0;

const btnPrev = document.getElementById('btnPrev');
const btnNext = document.getElementById('btnNext');
const progressFill = document.getElementById('progressFill');

function goToSlide(index) {
  // On borne l'index entre 0 et le nombre de slides - 1
  if (index < 0 || index >= totalSlides) return;

  // On retire l'animation d'entrée de l'ancienne slide, on l'ajoute à la nouvelle
  slides[currentSlide].classList.remove('active');
  currentSlide = index;
  slides[currentSlide].classList.add('active');

  // Mise à jour de la barre de progression en haut de l'écran
  const progress = ((currentSlide + 1) / totalSlides) * 100;
  progressFill.style.width = progress + '%';

  // On désactive visuellement la flèche "précédent" au tout début
  btnPrev.disabled = currentSlide === 0;

  // Si cette slide contient des points "reveal-step" (conclusions),
  // on repart à zéro : seul le premier point est visible, les autres
  // n'apparaîtront qu'au clic sur "Suivant" (voir goNext ci-dessous).
  const steps = slides[currentSlide].querySelectorAll('.reveal-step');
  steps.forEach((el, i) => el.classList.toggle('shown', i === 0));

  updateNextButtonState();
}

// Le bouton "Suivant" ne doit être désactivé que si on est sur la
// toute dernière slide ET qu'il n'y a plus aucun point caché à révéler.
// Sans cette vérification, sur la dernière slide le bouton se bloquait
// immédiatement et empêchait d'afficher les points 2 et 3.
function updateNextButtonState() {
  const steps = slides[currentSlide].querySelectorAll('.reveal-step');
  const shownCount = slides[currentSlide].querySelectorAll('.reveal-step.shown').length;
  const stepsRemaining = steps.length - shownCount;
  btnNext.disabled = (currentSlide === totalSlides - 1) && stepsRemaining === 0;
}

// "Suivant" ne change de slide que si tous les points de la slide
// actuelle sont déjà affichés. Sinon, il révèle simplement le point
// suivant un par un, comme si on avançait d'une mini-diapo.
function goNext() {
  const steps = slides[currentSlide].querySelectorAll('.reveal-step');
  if (steps.length > 0) {
    const shownCount = slides[currentSlide].querySelectorAll('.reveal-step.shown').length;
    if (shownCount < steps.length) {
      steps[shownCount].classList.add('shown');
      updateNextButtonState();
      return; // on reste sur la même slide, un point de plus est révélé
    }
  }
  goToSlide(currentSlide + 1);
}

btnPrev.addEventListener('click', () => goToSlide(currentSlide - 1));
btnNext.addEventListener('click', goNext);

// Navigation au clavier : flèches gauche/droite
document.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowRight') goNext();
  if (e.key === 'ArrowLeft') goToSlide(currentSlide - 1);
});


// On affiche la première slide au chargement
goToSlide(0);

// ============================================================
// COULEURS PARTAGEES (reprises depuis style.css pour rester cohérent)
// ============================================================
const COLORS = {
  accent: '#3E7BFA',
  accentVif: '#6E9CFF',
  blancCasse: '#F3F1EA',
  grisArdoise: '#8B96AC',
  fondCarte: '#131D33',
  vertClair: '#8FE3A6',
  vertFonce: '#1E8C4E',
};

// Une couleur distincte par continent, utilisée sur la carte et le nuage de points
const CONTINENT_COLORS = {
  'Europe': '#3E7BFA',
  'Asie': '#F2A65A',
  'Afrique': '#57C785',
  'Amérique du Nord': '#D95D9C',
  'Amérique du Sud': '#8B6EF2',
  'Océanie': '#E4D45A',
};

// ============================================================
// SLIDE 3 — CARTE DU MONDE (jsVectorMap)
// ============================================================
function initWorldMap() {
  // On calcule le score min et max pour construire un dégradé de couleur cohérent
  const scores = Object.values(DATA.map_data);
  const minScore = Math.min(...scores);
  const maxScore = Math.max(...scores);

  new jsVectorMap({
    selector: '#worldMap',
    map: 'world',
    backgroundColor: 'transparent',
    zoomButtons: false,
    regionStyle: {
      initial: { fill: '#2A3550', stroke: '#ffffff', strokeWidth: 0.6 },
      hover: { fill: COLORS.vertFonce },
    },
    series: {
      regions: [{
        values: DATA.map_data,
        attribute: 'fill',
        // dégradé du vert clair (score faible) au vert foncé (score élevé)
        scale: [COLORS.vertClair, COLORS.vertFonce],
        normalizeFunction: 'linear',
      }],
    },
    onRegionTooltipShow(event, tooltip, code) {
      const value = DATA.map_data[code];
      if (value !== undefined) {
        tooltip.text(tooltip.text() + ' : score ' + value.toFixed(2) + ' / 10');
      }
    },
  });
}

// ============================================================
// SLIDE 4 — TOP 10 ANIME (Chart.js, barres horizontales)
// ============================================================
let top10Chart;
let playInterval = null;
const YEARS = ['2021', '2022', '2023', '2024', '2025'];
let yearIndex = 0;

function renderTop10(year) {
  const rows = DATA.top10_by_year[year];
  const labels = rows.map(r => r.country);
  const values = rows.map(r => r.score);
  const colors = rows.map(r => CONTINENT_COLORS[r.continent] || COLORS.accent);

  document.getElementById('yearDisplay').textContent = year;

  if (!top10Chart) {
    const ctx = document.getElementById('top10Chart').getContext('2d');
    top10Chart = new Chart(ctx, {
      type: 'bar',
      data: {
        labels,
        datasets: [{ label: 'Score de bonheur', data: values, backgroundColor: colors, borderRadius: 6 }],
      },
      options: {
        indexAxis: 'y', // barres horizontales
        responsive: true,
        maintainAspectRatio: false,
        animation: { duration: 700, easing: 'easeOutQuart' },
        scales: {
          x: { min: 0, max: 8, ticks: { color: COLORS.grisArdoise }, grid: { color: 'rgba(255,255,255,0.06)' } },
          y: { ticks: { color: COLORS.blancCasse }, grid: { display: false } },
        },
        plugins: { legend: { display: false } },
      },
    });
  } else {
    // On met juste à jour les données : Chart.js anime la transition automatiquement
    top10Chart.data.labels = labels;
    top10Chart.data.datasets[0].data = values;
    top10Chart.data.datasets[0].backgroundColor = colors;
    top10Chart.update();
  }

  // On met en surbrillance le bouton de l'année active
  document.querySelectorAll('.year-buttons button').forEach(btn => {
    btn.classList.toggle('active', btn.dataset.year === year);
  });
}

function buildYearButtons() {
  const container = document.getElementById('yearButtons');
  YEARS.forEach(year => {
    const btn = document.createElement('button');
    btn.textContent = year;
    btn.dataset.year = year;
    btn.addEventListener('click', () => {
      stopPlay();
      yearIndex = YEARS.indexOf(year);
      renderTop10(year);
    });
    container.appendChild(btn);
  });
}

function stopPlay() {
  clearInterval(playInterval);
  playInterval = null;
  document.getElementById('playBtn').textContent = '▶ Lancer l\'animation';
}

document.getElementById('playBtn').addEventListener('click', () => {
  if (playInterval) {
    stopPlay();
    return;
  }
  document.getElementById('playBtn').textContent = '⏸ Pause';
  playInterval = setInterval(() => {
    yearIndex = (yearIndex + 1) % YEARS.length;
    renderTop10(YEARS[yearIndex]);
  }, 1500);
});

// ============================================================
// SLIDE 5 — NUAGE DE POINTS (Chart.js, bubble chart)
// ============================================================
function initScatterChart() {
  // On regroupe les pays par continent : un dataset Chart.js par continent
  // permet d'avoir une couleur + une légende par continent automatiquement.
  const byContinent = {};
  DATA.scatter_data.forEach(row => {
    if (!byContinent[row.continent]) byContinent[row.continent] = [];
    byContinent[row.continent].push({
      x: row.gdp,
      y: row.score,
      r: 4 + row.life_exp * 16, // on transforme la contribution en rayon de bulle (px)
      country: row.country,
    });
  });

  const datasets = Object.keys(byContinent).map(continent => ({
    label: continent,
    data: byContinent[continent],
    backgroundColor: (CONTINENT_COLORS[continent] || COLORS.accent) + 'CC',
  }));

  const ctx = document.getElementById('scatterChart').getContext('2d');
  new Chart(ctx, {
    type: 'bubble',
    data: { datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        x: { title: { display: true, text: 'Contribution du PIB au score', color: COLORS.grisArdoise }, ticks: { color: COLORS.grisArdoise }, grid: { color: 'rgba(255,255,255,0.06)' } },
        y: { title: { display: true, text: 'Score de bonheur', color: COLORS.grisArdoise }, ticks: { color: COLORS.grisArdoise }, grid: { color: 'rgba(255,255,255,0.06)' } },
      },
      plugins: {
        legend: { position: 'bottom', labels: { color: COLORS.blancCasse, boxWidth: 12 } },
        tooltip: {
          callbacks: {
            label(item) {
              const d = item.raw;
              return `${d.country} — score ${d.y.toFixed(2)}`;
            },
          },
        },
      },
    },
  });
}

// ============================================================
// SLIDE 6 — TREEMAP DES FACTEURS (ApexCharts)
// ============================================================
function initTreemapChart() {
  const series = [{
    data: DATA.treemap_data.map(item => ({ x: item.label, y: item.value })),
  }];

  const chart = new ApexCharts(document.querySelector('#treemapChart'), {
    chart: { type: 'treemap', height: '100%', background: 'transparent', toolbar: { show: false } },
    series,
    theme: { mode: 'dark' },
    colors: [COLORS.accent, COLORS.accentVif, '#57C785', '#F2A65A', '#D95D9C', '#8B6EF2'],
    dataLabels: {
      style: { fontSize: '13px', fontFamily: 'IBM Plex Sans' },
      formatter(text, op) { return [text, op.value.toFixed(3)]; },
    },
    plotOptions: { treemap: { distributed: true } },
  });
  chart.render();
}

// ============================================================
// SLIDE 7 — WATERFALL PAR PAYS (ApexCharts, barres flottantes)
// ============================================================
let waterfallChart;

function buildWaterfallSeries(countryData) {
  // On construit une suite de barres "flottantes" : chacune part du total
  // cumulé précédent et monte jusqu'au nouveau total cumulé.
  let cumulative = 0;
  const bars = [];

  bars.push({ x: 'Base\n(Dystopie + résidu)', y: [0, countryData.base] });
  cumulative = countryData.base;

  countryData.steps.forEach(step => {
    const start = cumulative;
    cumulative += step.value;
    bars.push({ x: step.label, y: [start, cumulative] });
  });

  bars.push({ x: 'Score total', y: [0, countryData.total] });
  return bars;
}

function renderWaterfall(countryName) {
  const countryData = DATA.waterfall_all[countryName];
  const bars = buildWaterfallSeries(countryData);

  // Couleur différente pour la base et le total (repères) vs les facteurs (accent)
  const barColors = bars.map((_, i) => (i === 0 || i === bars.length - 1) ? COLORS.blancCasse : COLORS.accent);

  if (!waterfallChart) {
    waterfallChart = new ApexCharts(document.querySelector('#waterfallChart'), {
      chart: { type: 'rangeBar', height: '100%', background: 'transparent', toolbar: { show: false }, animations: { speed: 500 } },
      theme: { mode: 'dark' },
      series: [{ data: bars }],
      plotOptions: { bar: { horizontal: false, columnWidth: '55%', distributed: true } },
      colors: barColors,
      dataLabels: { enabled: false },
      xaxis: { labels: { style: { colors: COLORS.grisArdoise, fontSize: '11px' } } },
      yaxis: { min: 0, labels: { style: { colors: COLORS.grisArdoise } } },
      legend: { show: false },
      grid: { borderColor: 'rgba(255,255,255,0.06)' },
    });
    waterfallChart.render();
  } else {
    waterfallChart.updateOptions({ colors: barColors });
    waterfallChart.updateSeries([{ data: bars }]);
  }
}

function buildCountrySelect() {
  const select = document.getElementById('countrySelect');
  DATA.waterfall_countries.forEach(country => {
    const option = document.createElement('option');
    option.value = country;
    option.textContent = country;
    select.appendChild(option);
  });
  select.value = 'France';
  select.addEventListener('change', () => renderWaterfall(select.value));
}

// ============================================================
// SLIDE 8 — CARTES KPI
// ============================================================
function renderKPIs() {
  const kpi = DATA.kpi;
  const container = document.getElementById('kpiRow');

  const cards = [
    { label: 'Pays le plus heureux (2025)', value: kpi.happiest_country, sub: `Score : ${kpi.happiest_score.toFixed(2)} / 10` },
    { label: 'Pays le moins heureux (2025)', value: kpi.saddest_country, sub: `Score : ${kpi.saddest_score.toFixed(2)} / 10` },
    { label: 'Variation moyenne mondiale', value: (kpi.variation >= 0 ? '+' : '') + kpi.variation.toFixed(2), sub: '2021 → 2025 (score moyen mondial)' },
  ];

  cards.forEach(card => {
    const div = document.createElement('div');
    div.className = 'kpi-card';
    div.innerHTML = `
      <p class="kpi-label">${card.label}</p>
      <p class="kpi-value">${card.value}</p>
      <p class="kpi-sub">${card.sub}</p>
    `;
    container.appendChild(div);
  });
}

// ============================================================
// INITIALISATION GENERALE
// On construit tous les graphiques dès le chargement de la page.
// IMPORTANT : chaque graphique est lancé dans son propre "safeRun".
// Sans ça, une seule erreur (ex : une librairie qui n'a pas chargé)
// bloquerait TOUS les graphiques suivants d'un coup.
// ============================================================
function safeRun(label, fn) {
  try {
    fn();
  } catch (err) {
    // L'erreur s'affiche dans la console du navigateur (touche F12)
    // avec le nom de la slide concernée, pour la retrouver facilement.
    console.error('Erreur lors de la construction de : ' + label, err);
  }
}

